func HasActWith(preds ...predicate.OneShotAct) predicate.OneShotItem {
	return predicate.OneShotItem(func(s *sql.Selector) {
		step := newActStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OneShotItem) predicate.OneShotItem {
	return predicate.OneShotItem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OneShotItem) predicate.OneShotItem {
	return predicate.OneShotItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OneShotItem) predicate.OneShotItem {
	return predicate.OneShotItem(sql.NotPredicates(p))
}
